The search itself is the usual backtracking walk, but the early checks avoid many useless starts. Counting the board first catches impossible words such as one asking for more `Z` characters than the board contains.

The word is reversed when its first letter appears more often than its last letter. Searching from a rare letter often cuts down the number of branches, especially with repeated characters. The board is marked in place with `'#'` and restored on every return.

```cpp
#include <algorithm>
#include <string>
#include <vector>
using namespace std;

class Solution {
private:
    bool dfs(vector<vector<char> >& board, const string& word,
             int row, int col, int index) {
        if (index == static_cast<int>(word.size())) {
            return true;
        }

        if (row < 0 || row >= static_cast<int>(board.size()) ||
            col < 0 || col >= static_cast<int>(board[0].size()) ||
            board[row][col] != word[index]) {
            return false;
        }

        char saved = board[row][col];
        board[row][col] = '#';

        bool found = dfs(board, word, row + 1, col, index + 1) ||
                     dfs(board, word, row - 1, col, index + 1) ||
                     dfs(board, word, row, col + 1, index + 1) ||
                     dfs(board, word, row, col - 1, index + 1);

        board[row][col] = saved;
        return found;
    }

public:
    bool exist(vector<vector<char> >& board, string word) {
        if (board.empty() || board[0].empty() || word.empty()) {
            return false;
        }

        int rows = static_cast<int>(board.size());
        int cols = static_cast<int>(board[0].size());

        if (static_cast<int>(word.size()) > rows * cols) {
            return false;
        }

        int boardCount[256] = {};
        for (const vector<char>& row : board) {
            for (char value : row) {
                boardCount[static_cast<unsigned char>(value)]++;
            }
        }

        int wordCount[256] = {};
        for (char value : word) {
            int code = static_cast<unsigned char>(value);
            wordCount[code]++;
            if (wordCount[code] > boardCount[code]) {
                return false;
            }
        }

        if (boardCount[static_cast<unsigned char>(word.front())] >
            boardCount[static_cast<unsigned char>(word.back())]) {
            reverse(word.begin(), word.end());
        }

        for (int row = 0; row < rows; ++row) {
            for (int col = 0; col < cols; ++col) {
                if (board[row][col] == word[0] &&
                    dfs(board, word, row, col, 0)) {
                    return true;
                }
            }
        }

        return false;
    }
};
```

Repeated letters are the difficult case because many neighboring cells can look valid. The frequency check handles impossible counts first, while reversing can make the first few choices rarer.

Time complexity: `O(R * C * 4^L)` in the worst case, plus `O(R * C + L)` for counting.

Space complexity: `O(L)` for recursion. The board is temporarily modified, then restored.

Kept the search close to the board. Every matching cell can be a starting point, and the recursive function checks the current letter before trying the four neighbors.

A used cell is changed to `'#'` for the current path. It is restored after the recursive calls, which lets another path use it later.

Dry run for `ABCCED` starts like this: `(0,0) A -> (0,1) B -> (0,2) C`. The search then moves down to the second `C`, continues to `E`, and finally reaches `D`.

```cpp
#include <vector>
#include <string>
using namespace std;

class Solution {
private:
    bool search(vector<vector<char> >& board, const string& word,
                int row, int col, int index) {
        if (index == static_cast<int>(word.size())) {
            return true;
        }

        if (row < 0 || row >= static_cast<int>(board.size()) ||
            col < 0 || col >= static_cast<int>(board[0].size()) ||
            board[row][col] != word[index]) {
            return false;
        }

        char original = board[row][col];
        board[row][col] = '#';

        bool found = search(board, word, row + 1, col, index + 1) ||
                     search(board, word, row - 1, col, index + 1) ||
                     search(board, word, row, col + 1, index + 1) ||
                     search(board, word, row, col - 1, index + 1);

        board[row][col] = original;
        return found;
    }

public:
    bool exist(vector<vector<char> >& board, string word) {
        if (board.empty() || board[0].empty() || word.empty()) {
            return false;
        }

        for (int row = 0; row < static_cast<int>(board.size()); ++row) {
            for (int col = 0; col < static_cast<int>(board[0].size()); ++col) {
                if (search(board, word, row, col, 0)) {
                    return true;
                }
            }
        }

        return false;
    }
};
```

Time complexity: `O(R * C * 4^L)` in the simple upper bound, where `L` is the word length.

Space complexity: `O(L)` for the recursion stack. The input board is changed temporarily and restored before returning.

Before starting recursion, this version checks two quick facts. The word cannot be longer than the number of cells, and every letter must appear enough times on the board.

It also starts from the less common end of the word when possible. A valid path can be read in reverse, so this does not change the answer. The visited matrix is cleared by backtracking after each failed branch.

For example, if the board has many `A` cells but only one `B`, a word beginning with many `A` characters is searched more cheaply after reversing it to begin with `B`.

```java
class Solution {
    private int rows;
    private int cols;
    private boolean[][] visited;

    public boolean exist(char[][] board, String word) {
        if (board.length == 0 || board[0].length == 0 || word.length() == 0) {
            return false;
        }

        rows = board.length;
        cols = board[0].length;

        if (word.length() > rows * cols) {
            return false;
        }

        int[] boardCount = new int[256];
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                boardCount[board[row][col]]++;
            }
        }

        int[] wordCount = new int[256];
        for (int i = 0; i < word.length(); i++) {
            wordCount[word.charAt(i)]++;
        }

        for (int i = 0; i < 256; i++) {
            if (wordCount[i] > boardCount[i]) {
                return false;
            }
        }

        if (boardCount[word.charAt(0)] > boardCount[word.charAt(word.length() - 1)]) {
            word = new StringBuilder(word).reverse().toString();
        }

        visited = new boolean[rows][cols];

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (search(board, word, row, col, 0)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean search(char[][] board, String word,
                           int row, int col, int index) {
        if (index == word.length()) {
            return true;
        }

        if (row < 0 || row >= rows || col < 0 || col >= cols ||
            visited[row][col] || board[row][col] != word.charAt(index)) {
            return false;
        }

        visited[row][col] = true;

        boolean found = search(board, word, row + 1, col, index + 1) ||
                        search(board, word, row - 1, col, index + 1) ||
                        search(board, word, row, col + 1, index + 1) ||
                        search(board, word, row, col - 1, index + 1);

        visited[row][col] = false;
        return found;
    }
}
```

Dry run: for a one-cell board containing `A` and word `A`, the search matches the cell, moves to index `1`, and immediately returns true. If the word needs two letters, the first recursive call reaches the end of the board and the result is false.

Time complexity: `O(R * C * 4^L)` after the counting checks.

Space complexity: `O(R * C + L)`, including the visited matrix and recursion stack. The board itself is not modified.

