class Solution {
    public boolean exist(char[][] board, String word) {
        for(int r=0; r<board.length; r++){
            for(int c=0; c<board[0].length; c++){
                if(board[r][c] == word.charAt(0) && solveWordSearch(board, word, 0, r, c)) return true;
            }
        }
        return false;
    }

    boolean solveWordSearch(char[][] board, String word, int idx, int r, int c){
        if(idx == word.length()) return true;

        if(r < 0 || r >= board.length || c < 0 || c >= board[0].length || board[r][c] != word.charAt(idx)) return false;

        int[][] directions = {{-1,0}, {0,1}, {1,0}, {0,-1}};

        char temp = board[r][c];
        board[r][c]='*';
        for(int[] dir : directions){
            int nextRow = r+dir[0];
            int nextCol = c+dir[1];            
            if(solveWordSearch(board, word, idx+1, nextRow, nextCol)) return true;   
        }
        board[r][c]=temp;

        return false;
    }
}
